The script must load a JSON file, apply a field renaming (user_name→name, user_email→email, user_age→age), and write valid JSON output. It should handle missing fields (output null), coerce the age field to integer when possible, and handle malformed JSON gracefully. Because the input is a JSON array, the script processes each object individually and can also accept a JSON object as input by wrapping it in a list.

```python
import json
import sys
import os

def convert_age(value):
    """Coerce a value to an integer if possible; otherwise return the original value."""
    if value is None:
        return None
    try:
        # If it's a float like 30.0, convert to int after checking if it's an integer value
        if isinstance(value, float):
            if value.is_integer():
                return int(value)
            return value
        if isinstance(value, int):
            return value
        # Try converting string or other type to int
        if isinstance(value, str):
            stripped = value.strip()
            if stripped == "":
                return None
            # Try int first, then float
            try:
                return int(stripped)
            except ValueError:
                try:
                    f = float(stripped)
                    if f.is_integer():
                        return int(f)
                    else:
                        return f
                except ValueError:
                    return value
        # For other types, attempt conversion
        return int(value)
    except (ValueError, TypeError):
        return value

def transform_record(record):
    """Rename fields and coerce age."""
    return {
        "name": record.get("user_name"),
        "email": record.get("user_email"),
        "age": convert_age(record.get("user_age"))
    }

def main():
    if len(sys.argv) != 3:
        print("Usage: python script.py <input.json> <output.json>", file=sys.stderr)
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2]

    try:
        with open(input_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except FileNotFoundError:
        print(f"Error: Input file not found: {input_path}", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON in input file: {e}", file=sys.stderr)
        sys.exit(1)

    # Handle both top-level array and top-level object
    if isinstance(data, list):
        records = data
    elif isinstance(data, dict):
        records = [data]
    else:
        print("Error: JSON content must be an array or object", file=sys.stderr)
        sys.exit(1)

    transformed = [transform_record(rec) for rec in records]

    try:
        with open(output_path, 'w', encoding='utf-8') as f:
            json.dump(transformed, f, indent=2, ensure_ascii=False)
        print(f"Successfully converted {len(transformed)} record(s) to {output_path}")
    except IOError as e:
        print(f"Error writing output file: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
